<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';header('Content-Type: application/json; charset=utf-8');if(!usuario_autenticado()){http_response_code(401);echo json_encode([]);exit;}$uid=(int)$_SESSION['usuario_id'];
$sql='SELECT c.id,IF(c.cliente_id=?,u_prof.ultima_atividade,u_cli.ultima_atividade) ultima_atividade,IF(c.cliente_id=?,u_prof.ultimo_logout,u_cli.ultimo_logout) ultimo_logout FROM conversas c JOIN profissionais p ON p.id=c.profissional_id JOIN usuarios u_prof ON u_prof.id=p.usuario_id JOIN usuarios u_cli ON u_cli.id=c.cliente_id WHERE c.cliente_id=? OR p.usuario_id=?';$stmt=$mysqli->prepare($sql);$stmt->bind_param('iiii',$uid,$uid,$uid,$uid);$stmt->execute();$dados=[];foreach($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $item)$dados[(int)$item['id']]=['online'=>usuario_esta_online($item),'texto'=>texto_presenca($item)];echo json_encode($dados,JSON_UNESCAPED_UNICODE);
